    public static PathIcon Create(Shape shape, Brush? brush = null)
    {
        var icon = new PathIcon
        {
            Data = Parse(shape), Width = shape.Size, Height = shape.Size,
            VerticalAlignment = VerticalAlignment.Center, HorizontalAlignment = HorizontalAlignment.Center,
        };
        if (brush is not null) icon.Foreground = brush;
        return icon;
    }

    /// <summary>A new instance each time: a geometry can only belong to one element.</summary>
    public static Geometry Parse(Shape shape) => (Geometry)XamlBindingHelper.ConvertValue(typeof(Geometry), shape.Data);
}
